"use client";

import { useState, useEffect } from "react";

const LOGO_LIGHT_DATA = "data:image/png;base64,";
const LOGO_DARK_DATA = "data:image/png;base64,";
const LOGO_SOLID_DATA = "data:image/png;base64,";

export default function BrandLogo({
  isDark = false,
  variant = null,
  className = "h-10 sm:h-11 md:h-12 lg:h-[52px] w-auto object-contain transition-transform duration-300 group-hover:scale-105 drop-shadow-sm",
  alt = "Nirvana Space - Built on Trust. Driven by Loyalty."
}) {
  const getSources = () => {
    if (variant === "solid") {
      return {
        target: "/images/logo.png",
        fallback: LOGO_SOLID_DATA
      };
    }
    if (isDark || variant === "dark") {
      return {
        target: "/images/logo-dark.png",
        fallback: LOGO_DARK_DATA
      };
    }
    return {
      target: "/images/logo-transparent.png",
      fallback: LOGO_LIGHT_DATA
    };
  };

  const sources = getSources();
  const [imgSrc, setImgSrc] = useState(sources.target);

  useEffect(() => {
    const s = getSources();
    setImgSrc(s.target);
  }, [isDark, variant]);

  return (
    <img
      src={imgSrc}
      alt={alt}
      onError={() => {
        const s = getSources();
        if (imgSrc !== s.fallback) {
          setImgSrc(s.fallback);
        }
      }}
      className={className}
      loading="eager"
      decoding="sync"
    />
  );
}
